#!/bin/sh
# wcurl — minimal hardened wrapper (illustrative, option A)
set -eu

CURL_MIN_NO_CLOBBER=7.83.0
CURL_MIN_PARALLEL=7.66.0
CURL_MIN_PARALLEL_MAX_HOST=8.16.0

curl_version() { curl --version | head -n1 | awk '{print $2}'; }
ver_ge() { [ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -n1)" = "$2" ]; }

sanitize_filename() {
  # reject path traversal / absolute paths
  case "$1" in
    */*|*..*|/*) echo "wcurl: unsafe filename: $1" >&2; exit 2 ;;
  esac
  printf '%s' "$1"
}

DRY_RUN=0
NO_DECODE=0
OUTPUT=""
CURL_OPTS=""
URLS=""

while [ $# -gt 0 ]; do
  case "$1" in
    --dry-run) DRY_RUN=1 ;;
    --no-decode-filename) NO_DECODE=1 ;;
    -o|-O|--output) shift; OUTPUT="$1" ;;
    --output=*) OUTPUT="${1#--output=}" ;;
    --curl-options) shift; CURL_OPTS="$CURL_OPTS $1" ;;
    --curl-options=*) CURL_OPTS="$CURL_OPTS ${1#--curl-options=}" ;;
    --) shift; while [ $# -gt 0 ]; do URLS="$URLS $1"; shift; done; break ;;
    -V|--version) curl --version; exit 0 ;;
    -h|--help) echo "usage: wcurl [options] URL..."; exit 0 ;;
    -*) echo "wcurl: unknown option: $1" >&2; exit 2 ;;
    *) URLS="$URLS $1" ;;
  esac
  shift
done

CV=$(curl_version)
if ! ver_ge "$CV" "$CURL_MIN_NO_CLOBBER"; then
  echo "wcurl: warning: curl $CV < $CURL_MIN_NO_CLOBBER — no-clobber unavailable, overwrite risk" >&2
fi

ARGS=""
if ver_ge "$CV" "$CURL_MIN_PARALLEL"; then ARGS="$ARGS --parallel"; fi
if ver_ge "$CV" "$CURL_MIN_PARALLEL_MAX_HOST"; then ARGS="$ARGS --parallel-max-host 5"; fi
if ver_ge "$CV" "$CURL_MIN_NO_CLOBBER"; then ARGS="$ARGS --no-clobber"; fi
ARGS="$ARGS --location --remote-time --globoff"

for u in $URLS; do
  case "$u" in
    *://*) : ;;
    *) u="https://$u" ;;
  esac
  if [ -n "$OUTPUT" ]; then
    fn=$(sanitize_filename "$OUTPUT")
    ARGS="$ARGS --output $fn"
  fi
  ARGS="$ARGS $u"
done

# NOTE: CURL_OPTS is whitespace-split by design (documented footgun).
# Never build from untrusted input.
CMD="curl$ARGS$CURL_OPTS"
if [ "$DRY_RUN" -eq 1 ]; then
  echo "$CMD"
  exit 0
fi
exec curl $ARGS $CURL_OPTS
